#!/usr/bin/env python3
"""Append targeted expansion paragraphs to notes under 400 words, then re-validate."""
import json, os, sys

BASE = "/home/hatch/workspace/apex-audit/docs/university/data/courses/_il29-build"

# key: (module_number_1based, note_index) -> expansion paragraph
EXP = {
(1,3): " One more operational habit: test your assume-breach posture with tabletop exercises, not just architecture diagrams. Pick a scenario — 'the CFO's laptop is compromised right now' — and walk the team through what the attacker can reach from that machine in the first hour. If the honest answer includes the file server, the backup system, or the domain controller, the design has gaps regardless of what the slide deck claims. Run this exercise quarterly; the gaps it finds become the next quarter's policy projects, which is how assume breach turns from a mindset into a roadmap.",
(2,0): " The rollback criterion deserves the same rigor as the flip criteria. Define it before you start: for example, 'if legitimate blocks exceed five per user per day in the pilot group for two consecutive days, we return the pilot to monitor mode and review.' A rollback plan you write during the crisis is not a plan. Also decide who can authorize the flip in each direction — the same person who owns the policy — so enforcement decisions never stall waiting for a committee. Staged rollouts with written forward and reverse criteria are what separate a controlled deployment from an outage with good intentions.",
(2,1): " In practice you verify signatures with the platform's own tooling: on Windows, Get-AuthenticodeSignature shows the signer and the chain status, and a Valid result means the signature is intact and chains to a trusted root — it does not mean the file is safe. Build the habit of checking the chain, not just the presence of a signature: a Valid signature from an unknown publisher is a fact to investigate, while a HashMismatch or NotSigned result on a file that claims to be vendor software is a finding. Record the signer subject and the thumbprint in your rule documentation so future-you can tell whether the vendor rotated their certificate or something changed unexpectedly.",
(2,2): " Treat the library as a supply chain: ask who curates it, how often it updates, and what happens when a listed application is found to be compromised. Your change process should include a periodic review of library-sourced rules — quarterly is the working default — where you confirm the entries you depend on are still current and still scoped correctly. If the platform ever flags a library entry as revoked or untrusted, you need a runbook entry for that day: which of your rules referenced it, what breaks if you pull it, and what the replacement rule looks like. Depending on a shared catalog without a plan for its failure modes is outsourcing judgment without retaining oversight.",
(2,3): " Measure the workflow or it will decay. Track three numbers weekly: median time from block to decision, the age of the oldest open request, and the approval rate by category. A median that creeps upward means the approvers are overloaded or the intake is capturing junk — either way, the business is learning that requests go nowhere. Publish the numbers to the approvers themselves; nothing fixes a slow queue like its owner seeing it in a chart. And keep an emergency lane genuinely fast: if the emergency path takes as long as the standard path, users will stop distinguishing them and every request will arrive marked urgent.",
(2,4): " For high-risk files, the examination happens under isolated conditions: a disposable virtual machine with no network access to production, snapshots so you can revert, and no credentials or sensitive data present. What you are looking for is behavior, not just identity — what the file tries to do when executed — and you record the observations in the ticket before deleting the VM. Never reuse the analysis VM for anything else, and never move the file to production 'because it looked fine in the sandbox.' The sandbox informs the verdict; the verdict still goes through the approval workflow with its evidence attached.",
(2,5): " Extend the same thinking beyond direct child processes. Scheduled tasks, services, WMI event subscriptions, and startup-folder entries are all ways to get code running without an obvious parent-child relationship — the persistence layer. Your policy should treat these as execution events subject to the same identity checks: a scheduled task launching an unknown binary is the same verdict as a user double-clicking it. When you audit an endpoint, enumerate these autostart locations alongside the running processes; attackers who cannot win the parent-child game will play the persistence game instead, and the allowlist must cover both boards.",
(3,0): " A subtle point: fences should inherit down the process tree. When a fenced application legitimately spawns an approved child — the browser's renderer, the updater — that child should run under a fence at least as strict as the parent's, not escape into an unfenced context. Otherwise the attacker only needs to compromise the allowed child to inherit its freedom. Define the expected child family per application explicitly, fence each member for its own function, and deny everything outside the family. The process tree is the unit of policy, not just the single process.",
(3,1): " The deeper variant of this pattern does not even need a new binary: the attacker abuses the legitimate binary's own arguments. The same powershell.exe that your admins use becomes the payload delivery vehicle when invoked with an encoded command — identity checks see the trusted binary, and only behavior analysis sees the attack. This is why mature ringfence design constrains not just which children may spawn but what arguments the sensitive ones may carry: script interpreters launched with encoded or hidden-window arguments by a document reader are never legitimate. When you write the fence, think in terms of behaviors — 'this app may not invoke script interpreters at all' — rather than binary names, because the names are the attacker's to choose.",
(3,2): " Note that the preview pane counts as opening. Many document-abuse attacks trigger from the preview handler without the user ever double-clicking the file — the mere act of selecting the message renders the content through the vulnerable handler chain. Your user training should say 'do not preview unexpected attachments' rather than 'do not open them,' and your fence design should assume the handler runs on preview. This is also why the email gateway's attachment handling matters as a complementary layer: the fewer crafted documents that reach the inbox, the fewer handler invocations your fences must survive.",
(3,4): " Do not forget the browser's loadable code: extensions, plugins, and helper objects execute inside the browser's context with its privileges. A malicious or compromised extension bypasses the child-process fence entirely because it never spawns anything — it simply acts. Your browser policy should therefore govern the extension inventory too: an approved extension list, ideally centrally managed, with the same approval workflow as applications. An unmanaged extension ecosystem on a fenced browser is a fenced front door with the windows open.",
(3,5): " Two legacy Office features deserve explicit mention in your fence design: DDE and OLE. Both are mechanisms by which a document pulls in external content or launches linked objects — legitimate in 1998, abused ever since. If the business does not use them, disable them outright via policy rather than fencing around them; a disabled feature needs no fence. If some legacy workflow genuinely depends on them, that workflow gets the full treatment from M02: documented, scoped to the machines that need it, ringfenced tightly, with a migration plan and a date. 'Legacy requires it' is a bridge, not a destination.",
(4,0): " Before removing anything, measure. Pull 30 days of privilege-use data: which users invoke admin rights, for what operations, and how often. You will typically find three groups: the handful with genuine recurring needs (their tasks become elevation rules), the large middle whose 'need' is one legacy installer (their need becomes a scoped rule plus a remediation ticket), and the long tail who simply have admin because everyone does (their need evaporates on inspection). This data does two jobs: it designs the replacement policies, and it defuses the political fight — 'we measured, and here is what you actually use' beats 'trust us' in every meeting where admin removal is contested.",
(4,1): " Keep interactive elevation and non-interactive privilege strictly separated in your design. Services and scheduled tasks that run with stored credentials or as SYSTEM are not 'elevation' in the just-in-time sense — they are standing privilege by another name, and they get their own inventory, their own review, and their own hardening (managed service accounts, credential rotation, minimal rights). The just-in-time workflow covers the human asking for temporary rights; the service inventory covers the machine acting with permanent ones. Auditing one while ignoring the other leaves half the privilege surface unexamined.",
(4,2): " Verify before you elevate. An elevation policy that approves 'the vendor installer' should still confirm the installer's integrity at approval time: compare its hash against the vendor's published value, confirm the signature chains correctly, and confirm you fetched it from the vendor's official distribution point. Elevating a trojaned installer with administrative rights is the worst possible outcome of this control — the policy that grants the privilege must also demand the evidence. Build the verification step into the intake form so it cannot be skipped under time pressure: no hash check, no elevation.",
(4,4): " Assume the attacker also steals session tokens, not just passwords — tokens can be replayed without the password ever being known. This is why the control pairs with session hygiene: short token lifetimes, and elevation decisions that re-verify rather than trusting an existing session blindly. The principle is the same as everywhere in this course: standing artifacts — passwords, tokens, privileges — are what attackers reuse. Shrink what stands, time-bound what is granted, and log every grant so the reuse window is visible.",
(4,5): " Design the emergency lane with the same care as the standard path, because emergencies are when discipline is weakest. The lane needs three things: a reachable approver (the on-call rotation, not 'whoever is awake'), the same evidence minimum (ticket number, application identity, window — no evidence-free elevations, ever), and a mandatory next-business-day review where the grant is re-examined with cool heads. Publish the lane's usage statistics monthly: a lane used twice a quarter is healthy; a lane used twice a week is a standard path avoiding scrutiny, and the review will show it.",
(5,0): " Cover the read direction with equal seriousness. Blocking writes stops exfiltration, but unrestricted reads from untrusted media invite malware in — the stick found in the parking lot is the classic delivery vector. The complete device policy states both directions per class: the field tech's registered drive may read and write, the conference-room PC may read presentation drives but never write to them, and unknown media is denied both directions. When you write the policy table, give every class two columns — read and write — and force an explicit decision in each. Blank cells become holes.",
(5,1): " You cannot govern devices you have not discovered, so the policy project starts with an inventory. Pull from asset management, but verify: check the helpdesk ticket history for 'my drive doesn't work' and 'can't access my phone' (each ticket names a device class in use), run a monitor-mode observation period logging every storage-device connection with its class and user, and survey the departments with legitimate needs (field ops, sales, executives). The inventory will surprise you — the lab equipment with its ancient data logger, the marketing team's camera cards — and each surprise is a row in the policy table that would otherwise have been a hole.",
(5,2): " Remember that effective access is the intersection of both layers: the share permissions and the NTFS permissions must agree, or the more permissive one wins. Document both in the share record, and verify with a test account in each role — reading the dialogs is not verification. The classic failure is the 'secure' share with Everyone:Read at the share level and Users:Full at the NTFS level, or vice versa; the effective access is whatever the union permits. Your migration checklist should include an effective-access test per role per share, recorded in the ticket, before you declare the migration complete.",
(5,3): " Standardize what goes on the issued drives. The provisioning checklist should state exactly what is installed (imaging tools, drivers, the approved transfer utility), what is forbidden (customer data at rest — the drive is a transport, not storage), and how the drive is labeled and tracked (asset tag tied to the serial in the register). When a drive is lost, this standard is what makes the exposure assessment fast: 'per the provisioning standard, no customer data was on it' is an answer you can give confidently only if the standard exists and is followed. Audit the issued drives annually against the checklist.",
(6,0): " The endpoint firewall also feeds the EDR's network visibility: connection logs with process attribution are among the highest-value telemetry for threat hunting, because they show which process talked to where — the question every investigation asks first. Ensure the firewall logs are forwarded to the same store as the Detect alerts so the triage workflow sees them together: the blocked lateral attempt and the process tree in one view. A firewall whose logs stay local is a witness that never testifies.",
(6,1): " Give every rule a lifecycle, not just a creation. The rule record states the owner, the justification, the review date, and the condition under which it is removed (project end, decommission, migration complete). Review the rule set on the same cadence as the allowlist — quarterly at minimum — and expire rules whose justification has lapsed. Firewall rules, like allowlist entries, rot: the 'temporary' vendor access from last year's migration is still open, and the scanner will find it before you remember it.",
(6,2): " Verify the lateral-movement policy across transports, not just the famous ports. Denying TCP 445 while the same file-sharing capability is reachable over an alternate transport is a wall with a side door. Your validation should attempt the lateral movement from a lab machine using the actual techniques — not just read the rule list — and confirm each path is denied and logged. The test matrix covers the protocol families your environment actually runs, including the ones the server team forgot to mention.",
(6,3): " Treat DNS as part of the egress policy, not as someone else's problem. Malware that cannot open a direct connection will try DNS tunneling — encoding data in DNS queries — which sails through a firewall that filters connections but not name resolution. The complete design points endpoints at company resolvers, logs and inspects DNS queries, and treats anomalous DNS (high entropy, unusual query rates, tunneling patterns) as the detection signal it is. The M07 triage workflow should include a DNS-history check for any host under investigation.",
(6,4): " Harden the jump host like the crown jewel it is: no internet browsing, no email, allowlisted applications only, every session logged, and access requiring phishing-resistant authentication. A compromised jump host inherits its administrative reach — the chokepoint becomes the prize. Review who holds jump-host access quarterly, because the list grows silently and every name on it is a path to every server. The jump host is the one machine where 'inconvenient security' is the entire point.",
(6,5): " Record every exception in the change system with the same five fields as the allowlist: requester, justification, scope, expiry, approver. The firewall exception register is audited alongside the others, and 'temporary vendor access' without an expiry is the rule most likely to be found open two years later. When the auditor asks why port X is open to subnet Y, the register should answer in one lookup — that is the difference between a managed firewall and a collection of rules.",
(7,0): " Design the alert routing before the alerts arrive. Critical-severity alerts page the on-call analyst; high-severity alerts land in the priority queue with a one-hour triage SLA; everything else flows to the standard queue. Route by asset criticality too — the domain controller's medium is the kiosk's critical. And build the queue dashboards around the runbook's verdicts, not raw counts: 'alerts triaged to incident this week' is a security metric, 'total alerts' is just weather. The routing design is what keeps the 2 AM alert from waiting until 9 AM.",
(7,2): " Close the loop between triage and prevention. Every incident verdict should produce at least one candidate policy improvement: a new ringfence behavior to deny, an allowlist rule to tighten, an egress destination to remove. Track these as follow-up tickets owned by the policy team, not as informal suggestions — the SOC sees the attacks, the policy team owns the gates, and the feedback ticket is the bridge. A SOC whose findings never change policy is an expensive observation deck.",
(7,3): " Set handoff SLAs with the MDR provider in the contract, not in the crisis. Define the severity-to-response-time mapping, the escalation path when the SLA is missed, and the format of the verdict that comes back — because the feedback is what tunes your runbook. Review the handoff quality quarterly with real tickets: were the packages complete, were the asks specific, did the verdicts come back in time to act? The MDR relationship is operated like any vendor relationship: measured, reviewed, and improved.",
(7,4): " Version the runbook and review it on a schedule — monthly for the active sections, quarterly cover to cover. Every triage that teaches something new produces a runbook update: a new example in a verdict branch, a tightened escalation criterion, a new tuning rule. Keep a changelog so analysts can see what changed and why; a runbook that silently mutates loses trust. The review meeting is short when the changelog does the talking: what did we learn, what did we change, what needs re-tuning.",
(8,0): " Deliver the baseline through the same channel as the rest of your configuration management — Group Policy for domain-joined machines, the MDM for the mobile fleet — so the baseline inherits the existing change control, targeting, and reporting. Do not manage Defender through a side channel with its own console and its own process; the side channel becomes the thing everyone forgets during incidents. One configuration pipeline, one change record, one place to check what was pushed and when.",
(8,1): " Watch the interplay between scan settings and exclusions: aggressive heuristic levels plus a broad exclusion list is the worst combination — maximum noise where you look, blindness where you do not. Tune them as a pair: set the protection level you can actually operate (alerts your SOC will triage, performance your users will tolerate), then keep the exclusion list as short as the narrowness ladder allows. The baseline document should record both decisions together with the reasoning, so the next operator understands the balance rather than inheriting half of it.",
(8,3): " Automate the drift check — a scheduled task or pipeline job that runs the comparison, files the report, and opens tickets for divergences above the threshold. Manual drift review works for twenty machines and collapses at two hundred; the automation is what makes the control scale. Keep the automation's own health monitored: a drift job that silently stopped running is worse than no job, because the dashboard still shows the last green report. Monitor the monitor.",
(8,4): " Keep one exceptions register, not three. The allowlist exceptions, the Defender exclusions, and the firewall exceptions all describe deliberate blind spots or openings — review them together quarterly, because a machine with an exclusion in all three is a machine with no controls left. The joint review is where the dangerous combinations surface: the unsigned tool that is allowlisted, excluded from scanning, and granted firewall exceptions is a policy decision that deserves executive visibility, not three separate tickets nobody connected.",
(8,5): " Run the quarterly review as a business meeting, not a technical deep dive. The operator brings the drift trend, the exclusion register with upcoming reviews, and one proposed change with pilot data — the leadership brings the risk appetite. Twenty minutes, three artifacts, decisions recorded. This cadence is what keeps the baseline a living standard instead of a document: the review is where stale exclusions die, where drift patterns get resourced, and where the next quarter's hardening is agreed. Boring, regular, effective.",
}

def main():
    fixed = []
    for n in range(1, 9):
        path = os.path.join(BASE, "batch-A-m%02d.json" % n)
        with open(path) as f:
            m = json.load(f)
        changed = False
        for i, note in enumerate(m["notes"]):
            wc = len(note["body"].split())
            if wc < 400:
                key = (n, i)
                if key not in EXP:
                    print("MISSING expansion for module %d note %d (wc=%d)" % (n, i, wc))
                    sys.exit(1)
                note["body"] = note["body"] + " " + EXP[key]
                new_wc = len(note["body"].split())
                assert 400 <= new_wc <= 900, "module %d note %d now %d words" % (n, i, new_wc)
                changed = True
                fixed.append((n, i, wc, new_wc))
        if changed:
            tmp = path + ".tmp"
            with open(tmp, "w") as f:
                json.dump(m, f, indent=1, ensure_ascii=False)
                f.write("\n")
            os.replace(tmp, path)
    print("Expanded %d notes:" % len(fixed))
    for n, i, before, after in fixed:
        print("  M%02d note %d: %d -> %d words" % (n, i, before, after))

if __name__ == "__main__":
    main()
